/* @lc app=leetcode id=1345 lang=kotlin */
class Solution { fun minJumps(arr: IntArray): Int = arr.indices.groupBy { arr[it] }.toMutableMap().let { map -> IntArray(arr.size) { -1 }.also { dist -> dist[0] = 0 }.let { dist -> ArrayDeque<Int>().apply { add(0) }.run { generateSequence { removeFirstOrNull() }.forEach { u -> if (u == arr.size - 1) return dist[u] else ((map.remove(arr[u]) ?: emptyList()) + listOf(u + 1, u - 1)).filter { it in arr.indices && dist[it] == -1 }.forEach { v -> dist[v] = (dist[u] + 1).also { add(v) } } }.let { 0 } } } } }